import {verifiedQuestSource} from './quest-runtime.js';
import {readEngineTexts,engineTextBytes,engineTextWorkshop} from './engine-text.js';
import {disassembleScript,decodeScriptText} from './script-engine.js';
import {encodedText} from './item-maker.js';
import {verifiedFRLGSource} from './verified-frlg.js';
import {wrapDialogue} from './world-model.js';
const BASE=0x08000000;
const idle=()=>new Promise(resolve=>setTimeout(resolve,0));
function cancelled(){const e=Error('Dialogue indexing cancelled.');e.name='AbortError';return e;}
// Map script headers contain direct entries (1,3,5,6,7) and conditional
// tables (2,4). See pret/pokefirered include/constants/map_scripts.h.
export function mapDialogueRoots(reader,map){
 const b=reader.bytes,v=new DataView(b.buffer,b.byteOffset,b.byteLength),valid=(at,n=1)=>Number.isInteger(at)&&at>=512&&at+n<=b.length,ptr=at=>valid(at,4)?v.getUint32(at,true)-BASE:-1,roots=[];let skipped=0;
 const events=reader.events(map);for(const event of [...(events.npcs||[]),...(events.signs||[]),...(events.triggers||[])])if(valid(event.script))roots.push(event.script);
 const table=map.scripts;if(!valid(table))return{roots,skipped};let ended=false;
 for(let i=0;i<32;i++){const at=table+i*5;if(!valid(at)){break;}const type=b[at];if(!type){ended=true;break;}const target=ptr(at+1);if(type>7||!valid(target)){skipped++;break;}
  if(type===2||type===4){let done=false;for(let j=0;j<128;j++){const row=target+j*8;if(!valid(row,2))break;if(!v.getUint16(row,true)){done=true;break;}const script=ptr(row+4);if(!valid(row,8)||!valid(script)){skipped++;break;}roots.push(script);}if(!done)skipped++;}
  else roots.push(target);
 }if(!ended)skipped++;return{roots:[...new Set(roots)],skipped};
}
export async function indexROMDialogue(reader,progress=()=>{},{shouldContinue=()=>true,scanPointers=true}={}){
 const byAddress=new Map(),cache=new Map();let skipped=0,tablesSkipped=0,work=0;
 const check=()=>{if(!shouldContinue())throw cancelled();};
 for(let i=0;i<reader.maps.length;i++){
  check();const map=reader.maps[i];let roots;try{const result=mapDialogueRoots(reader,map);roots=result.roots;tablesSkipped+=result.skipped;}catch{tablesSkipped++;continue;}
  for(const at of roots){if(++work%8===0){progress(i,reader.maps.length,'scripts');await idle();check();}if(!cache.has(at)){try{cache.set(at,disassembleScript(reader.bytes,at,reader.engine,true).texts);}catch{cache.set(at,[]);skipped++;}}
   for(const t of cache.get(at)){let row=byAddress.get(t.address);if(!row){row={address:t.address,text:t.text,references:[],maps:[],mapKeys:[],extraReferences:[],extraReferenceCount:0};byAddress.set(t.address,row);}for(const ref of t.references)if(!row.references.includes(ref))row.references.push(ref);const key=map.key??map.label??String(i);if(!row.mapKeys.includes(key)){row.mapKeys.push(key);row.maps.push(map.label||key);}}
  }
  if(i%8===0){progress(i,reader.maps.length,'scripts');await idle();}
 }
 // Pointer matches outside decoded commands are diagnostic only. They may be
 // data or unrelated bytes and must never be rewritten as guessed references.
 if(scanPointers&&byAddress.size){const b=reader.bytes,v=new DataView(b.buffer,b.byteOffset,b.byteLength),known=new Map([...byAddress].map(([at,row])=>[at,new Set(row.references)]));for(let start=512;start+4<=b.length;start+=262144){check();const end=Math.min(start+262144,b.length-3);for(let at=start;at<end;at++){if(b[at+3]!==8&&b[at+3]!==9)continue;const address=v.getUint32(at,true)-BASE,row=byAddress.get(address);if(row&&!known.get(address).has(at)){row.extraReferenceCount++;if(row.extraReferences.length<64)row.extraReferences.push(at);}}progress(end,b.length,'pointers');await idle();}}
 check();return{rows:[...byAddress.values()],skipped,tablesSkipped,scripts:cache.size};
}
export function validateTextPatch(bytes,address,patch){
 if(!Number.isInteger(address)||address<512||address>=bytes.length||!patch||typeof patch.original!=='string'||typeof patch.text!=='string'||!Array.isArray(patch.references)||!patch.references.length||patch.references.length>4096)throw Error('Invalid ROM dialogue edit.');
 if(decodeScriptText(bytes,address).text!==patch.original)throw Error('The original dialogue changed. Reopen the matching source ROM.');
 const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);for(const at of patch.references)if(!Number.isInteger(at)||at<512||at+4>bytes.length||v.getUint32(at,true)!==0x08000000+address)throw Error('A dialogue reference no longer matches its source.');
 const text=encodedText(patch.text);if(text.length>8192)throw Error('Dialogue exceeds 8,192 encoded bytes.');return text;
}
export function installTextEdits(project,reader,hash,output){const edits=project.textEdits?.[hash]||{},reports=[];if(!Object.keys(edits).length)return reports;const menuRows=Object.values(edits).some(p=>p?.kind==='engine')?readEngineTexts(reader,hash):[];const used=new Set();for(const[key,p]of Object.entries(edits)){let address=Number(key),bytes;if(p.kind==='engine'){const row=menuRows.find(r=>r.id===p.slotId);if(!row||key!=='engine:'+row.id||p.original!==row.text||p.references?.length!==1||p.references[0]!==row.reference)throw Error('The native menu edit does not match its verified slot.');address=row.address;bytes=engineTextBytes(row,p.text);}else{bytes=validateTextPatch(reader.bytes,address,p);}for(const ref of p.references){if(used.has(ref))throw Error('Overlapping dialogue edits.');used.add(ref);}const to=output.allocate(bytes,'Dialogue at '+address.toString(16));for(const ref of p.references)output.int(ref,0x08000000+to);reports.push('Dialogue 0x'+address.toString(16)+': '+p.references.length+' verified references relocated.');}return reports;}
export function ROMTextWorkshop(api){let index=null,reader=null,hash=null;const $=s=>document.querySelector(s),esc=api.esc;async function open(){const session=api.session();if(!session)throw Error('Open the original ROM first.');if(reader!==session.reader||!index){const nextReader=session.reader,nextHash=session.id,currentProject=api.project();api.modal('Indexing dialogue','<p id="textProgress">Reading map event scripts…</p>');const progressNode=$('#textProgress'),active=()=>api.session()?.reader===nextReader&&api.project()===currentProject&&$('#textProgress')===progressNode&&progressNode?.isConnected&&$('#dialog')?.open!==false;try{const nextIndex=await indexROMDialogue(nextReader,(n,total,phase)=>{if(active())progressNode.textContent=phase==='pointers'?'Checking shared pointers: '+Math.round(n/total*100)+'%':n+' / '+total+' maps';},{shouldContinue:active});if(!active())return;reader=nextReader;hash=nextHash;index=nextIndex;}catch(e){if(e.name==='AbortError')return;throw e;}}api.modal('ROM dialogue',`<p>Search NPC, sign, trigger and map-entry dialogue. ${index.skipped} unsupported scripts and ${index.tablesSkipped} unsupported map-script tables were skipped. Menu labels are edited separately below.</p><button id="engineTextOpen" type="button">Native menu text</button><input id="romTextQuery" type="search" placeholder="Find dialogue"><div id="romTextRows"></div><button id="romTextMore" type="button">Show more</button>`);$('#engineTextOpen').onclick=()=>{try{engineTextWorkshop(api).open();}catch(e){api.error(e);}};let limit=30;const draw=()=>{const query=$('#romTextQuery').value.toLowerCase(),rows=index.rows.filter(r=>(api.project().textEdits?.[hash]?.[r.address]?.text??r.text).toLowerCase().includes(query));$('#romTextRows').innerHTML=rows.slice(0,limit).map(r=>`<button class="studio-record" data-text="${r.address}" type="button"><span><b>${esc((api.project().textEdits?.[hash]?.[r.address]?.text??r.text).slice(0,130))}</b><small>${esc(r.maps.join(', '))} · ${r.references.length} decoded references${r.extraReferenceCount?' · '+r.extraReferenceCount+' other pointer matches':''}</small></span></button>`).join('');$('#romTextMore').hidden=limit>=rows.length;document.querySelectorAll('[data-text]').forEach(b=>b.onclick=()=>edit(index.rows.find(r=>r.address===+b.dataset.text)));};$('#romTextQuery').oninput=()=>{limit=30;draw();};$('#romTextMore').onclick=()=>{limit+=30;draw();};draw();}
 function edit(row){const prior=api.project().textEdits?.[hash]?.[row.address],writable=reader.engine==='frlg'||reader.engine==='rse';api.modal('Edit ROM dialogue',`<p>${row.references.length} decoded references across ${row.mapKeys?.length||row.maps.length} maps will use this text.</p>${row.extraReferenceCount?`<details><summary>${row.extraReferenceCount} other pointer matches</summary><p>These matches are outside decoded commands. They may be data or other scripts; they retain the original text.</p><p>${row.extraReferences.map(at=>'0x'+at.toString(16).toUpperCase()).join(', ')}${row.extraReferenceCount>64?' (first 64 shown)':''}</p></details>`:''}<textarea id="romTextValue" rows="8" ${writable?'':'readonly'}></textarea><button id="romTextFit" type="button">Wrap into text-box pages</button><div class="dialogue-preview" id="romTextPreview"></div><button id="romTextReset" type="button">Restore source text</button>${writable?'':'<p>Read-only: writeback is not verified for this engine.</p>'}`,writable?()=>{const patch={original:row.text,text:$('#romTextValue').value,references:row.references};validateTextPatch(reader.bytes,row.address,patch);api.change(()=>{const p=api.project();p.textEdits??={};p.textEdits[hash]??={};p.textEdits[hash][row.address]=patch;});api.toast('Dialogue saved to project.');}:null,writable?'Save dialogue':'Done');$('#romTextValue').value=prior?.text??row.text;const preview=()=>{$('#romTextPreview').textContent=$('#romTextValue').value.replaceAll('\\n','\n').replaceAll('\\p','\n\n').replaceAll('\\l','\n');};$('#romTextValue').oninput=preview;$('#romTextFit').onclick=()=>{$('#romTextValue').value=wrapDialogue($('#romTextValue').value);preview();};$('#romTextReset').onclick=()=>{api.change(()=>{if(api.project().textEdits?.[hash])delete api.project().textEdits[hash][row.address];});open().catch(api.error);};preview();}
 return{open};}
